FROM user_point_ledger
WHERE user_id = #{userId}
ORDER BY created_at DESC, id DESC
LIMIT #{size} OFFSET #{offset}

SELECT id, user_id, event_type, reference_id, points, created_at
FROM user_point_ledger

    AND user_id = #{userId}
    AND event_type = #{eventType}
    AND created_at >= #{from}
    AND created_at <= #{to}

ORDER BY created_at DESC, id DESC
LIMIT #{size} OFFSET #{offset}

